SELECT /* LGVATT20011.retrieveResultExistsFlag */
       DECODE(count(1), 0, 'N', 'Y') as exists_flag
FROM   tb_att_result_n ar /* 실적근태 */
WHERE  ar.subsidiary_code             = #{LGVHR_PROJECT_SESSION.subsidiaryCode}
AND    ar.time_and_attendance_date    = TO_DATE(#{attendanceYyyymmdd}, 'DDMMYYYY')
AND    ar.employee_no                 = #{employeeNo}
